import{_ as r,o as t,c as e,a2 as l}from"./chunks/framework.BV21bweQ.js";const _=JSON.parse('{"title":"鸽族","description":"","frontmatter":{},"headers":[],"relativePath":"表层/种族/鸽族.md","filePath":"表层/种族/鸽族.md","lastUpdated":1787066340000}'),o={name:"表层/种族/鸽族.md"};function i(n,a,s,h,d,c){return t(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="鸽族" tabindex="-1">鸽族 <a class="header-anchor" href="#鸽族" aria-label="Permalink to &quot;鸽族&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>鸽族是羽族之一，体型偏小，以极高的飞行灵活性著称。鸽族飞行速度与耐力不如鹰族，但灵活性极高。鸽族生性聪慧，喜欢集体行动，向往秩序下的安稳生活与和平日子。</p><hr><h2 id="体貌特征" tabindex="-1">体貌特征 <a class="header-anchor" href="#体貌特征" aria-label="Permalink to &quot;体貌特征&quot;">​</a></h2><ul><li><strong>体格</strong>：羽族中体格偏小的一族。</li><li><strong>羽毛</strong>：羽毛大多为洁净的白色。</li><li><strong>翅膀</strong>：羽族部分分支背后生有双翅，具备飞行能力；鸽族飞行速度与耐力不如鹰族，但灵活性极高。</li><li><strong>骨骼</strong>：骨骼轻盈但强度极高，属羽族共同特征。</li></ul><hr><h2 id="种族特质" tabindex="-1">种族特质 <a class="header-anchor" href="#种族特质" aria-label="Permalink to &quot;种族特质&quot;">​</a></h2><ul><li><strong>聪慧</strong>：生性聪慧，具备较强的灵活应变与策略规划能力。</li><li><strong>集体行动</strong>：喜欢集体行动，善于通过群体协作达成目标。</li><li><strong>秩序偏好</strong>：向往秩序下的安稳生活，对混乱有本能的排斥。</li><li><strong>和平倾向</strong>：追求和平，不倾向于以暴力解决争端。</li></ul><hr><h2 id="历史" tabindex="-1">历史 <a class="header-anchor" href="#历史" aria-label="Permalink to &quot;历史&quot;">​</a></h2><p>在鹰族主导的黑暗时代中，鸽族处于边缘位置，具体参与情况未见明确记录。</p><hr><h2 id="现状" tabindex="-1">现状 <a class="header-anchor" href="#现状" aria-label="Permalink to &quot;现状&quot;">​</a></h2><p>鸽族在政治动荡与黑暗时代中<strong>处境不明</strong>——不如鹤族隐逸，亦不如鹰族强势。鸽族无核心剧情参与，在动荡中保持着相对低调的姿态。</p><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./鹰族">鹰族</a></li><li><a href="./鹤族">鹤族</a></li></ul><hr>',19)])])}const g=r(o,[["render",i]]);export{_ as __pageData,g as default};
